CREATE DOMAIN assay_b132_alter_routine.text AS pg_catalog.text;
CREATE FUNCTION assay_b132_alter_routine.f() RETURNS integer AS $$ SELECT 1 $$ LANGUAGE sql SET search_path TO pg_catalog;
SET search_path TO pg_catalog, assay_b132_alter_routine;
ALTER ROUTINE assay_b132_alter_routine.f() RESET search_path;
DO $verify_path$
BEGIN
  IF current_setting('search_path') <> 'pg_catalog, assay_b132_alter_routine' THEN
    RAISE EXCEPTION 'ALTER_ROUTINE_CHANGED_SESSION_PATH: %', current_setting('search_path');
  END IF;
  INSERT INTO assay_b132_alter_routine.receipt (verified) VALUES (true);
END
$verify_path$;
-- ASSAY-FOCUS: alter-routine-reset-keeps-session-path
CREATE TABLE assay_b132_alter_routine.task (status text CHECK (status IN ('open', 'closed')));

cases.assertion:
BEGIN;
DO $$
